package org.sailinguk.racecam;
import android.app.*;import android.os.*;import android.Manifest;import android.content.pm.PackageManager;import android.graphics.SurfaceTexture;import android.hardware.camera2.*;import android.media.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 TextureView preview; TextView status; TextView telemetryStatus; RaceControlRuntime raceControl; RaceCamMqttTelemetry telemetry; CameraDevice camera; CameraCaptureSession session; HandlerThread thread; Handler handler; MediaCodec encoder; Surface encodeSurface; ServerSocket server; volatile boolean running=true; volatile byte[] config; volatile long frames=0; final CopyOnWriteArrayList<ArrayBlockingQueue<byte[]>> clients=new CopyOnWriteArrayList<>();
 void show(String s){runOnUiThread(()->status.setText(s));}
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Sailing-UK RaceCam | H.264 720p / 25 fps / 2 Mbps");l.addView(t);preview=new TextureView(this);l.addView(preview,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(this);status.setText("Starting camera");l.addView(status);telemetryStatus=new TextView(this);telemetryStatus.setText("GPS telemetry: not paired");l.addView(telemetryStatus);TextView raceStatus=new TextView(this);raceStatus.setText("Race timing: not paired");l.addView(raceStatus);setContentView(l);try{raceControl=new RaceControlRuntime(getSharedPreferences("racecam_pairing",MODE_PRIVATE),raceStatus);}catch(Exception e){raceStatus.setText("Race timing: configuration required");}startTelemetryIfConfigured();thread=new HandlerThread("camera");thread.start();handler=new Handler(thread.getLooper());if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},42);else openCamera();new Thread(this::serve,"http").start();}
 void startTelemetryIfConfigured(){android.content.SharedPreferences p=getSharedPreferences("racecam_pairing",MODE_PRIVATE);String host=p.getString("mqtt_host","");if(host.isEmpty())return;telemetry=new RaceCamMqttTelemetry(this,msg->runOnUiThread(()->telemetryStatus.setText("GPS telemetry: "+msg)));if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},43);return;}telemetry.start(host,p.getInt("mqtt_port",8883),p.getString("mqtt_user",""),p.getString("mqtt_password",""),p.getString("mqtt_topic",""),p.getString("device_id",""));}
 void openCamera(){if(!preview.isAvailable()){preview.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){openCamera();}public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){}public boolean onSurfaceTextureDestroyed(SurfaceTexture t){return true;}public void onSurfaceTextureUpdated(SurfaceTexture t){} });return;}try{MediaFormat f=MediaFormat.createVideoFormat("video/avc",1280,720);f.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);f.setInteger(MediaFormat.KEY_BIT_RATE,2000000);f.setInteger(MediaFormat.KEY_FRAME_RATE,25);f.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,2);encoder=MediaCodec.createEncoderByType("video/avc");encoder.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);encodeSurface=encoder.createInputSurface();encoder.start();new Thread(this::drain,"h264-encoder").start();CameraManager mgr=(CameraManager)getSystemService(CAMERA_SERVICE);String id=null;for(String c:mgr.getCameraIdList()){Integer facing=mgr.getCameraCharacteristics(c).get(CameraCharacteristics.LENS_FACING);if(facing!=null&&facing==CameraCharacteristics.LENS_FACING_BACK){id=c;break;}}if(id==null)id=mgr.getCameraIdList()[0];mgr.openCamera(id,new CameraDevice.StateCallback(){public void onOpened(CameraDevice c){camera=c;configure();}public void onDisconnected(CameraDevice c){c.close();}public void onError(CameraDevice c,int e){c.close();show("Camera error "+e);}},handler);}catch(Exception e){show("Setup: "+e);}}
 void configure(){try{SurfaceTexture tex=preview.getSurfaceTexture();tex.setDefaultBufferSize(1280,720);Surface display=new Surface(tex);CaptureRequest.Builder req=camera.createCaptureRequest(CameraDevice.TEMPLATE_RECORD);req.addTarget(display);req.addTarget(encodeSurface);req.set(CaptureRequest.CONTROL_AE_TARGET_FPS_RANGE,new android.util.Range<Integer>(25,25));camera.createCaptureSession(Arrays.asList(display,encodeSurface),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){session=s;try{s.setRepeatingRequest(req.build(),null,handler);show("H.264 active | Wi-Fi port 8088");}catch(Exception e){show("Capture: "+e);}}public void onConfigureFailed(CameraCaptureSession s){show("Camera configuration failed");}},handler);}catch(Exception e){show("Configure: "+e);}}
 void drain(){MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(running){try{int i=encoder.dequeueOutputBuffer(info,100000);if(i==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat f=encoder.getOutputFormat();ByteArrayOutputStream o=new ByteArrayOutputStream();for(String key:new String[]{"csd-0","csd-1"}){ByteBuffer b=f.getByteBuffer(key);if(b!=null){byte[] x=new byte[b.remaining()];b.get(x);o.write(x);}}config=o.toByteArray();}else if(i>=0){ByteBuffer b=encoder.getOutputBuffer(i);if(b!=null&&info.size>0){b.position(info.offset);b.limit(info.offset+info.size);byte[] x=new byte[info.size];b.get(x);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)config=x;else{frames++;for(ArrayBlockingQueue<byte[]> q:clients){if(!q.offer(x)){q.poll();q.offer(x);}}}}encoder.releaseOutputBuffer(i,false);}}catch(Exception e){if(running)show("Encoder: "+e);break;}}}
 void serve(){try{server=new ServerSocket(8088);server.setSoTimeout(1000);while(running){try{Socket s=server.accept();new Thread(()->client(s),"http-client").start();}catch(SocketTimeoutException e){}}}catch(Exception e){show("HTTP: "+e);}}
 void client(Socket s){ArrayBlockingQueue<byte[]> q=null;try{s.setSoTimeout(4000);InputStream in=s.getInputStream();ByteArrayOutputStream line=new ByteArrayOutputStream();int c;while((c=in.read())!=-1&&c!=10&&line.size()<1024)line.write(c);String request=line.toString("UTF-8");OutputStream out=s.getOutputStream();if(request.startsWith("GET /status")){byte[] b=("H264 frames="+frames+" clients="+clients.size()).getBytes("UTF-8");out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: "+b.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(b);}else if(request.startsWith("GET /h264")){q=new ArrayBlockingQueue<>(50);out.write("HTTP/1.1 200 OK\r\nContent-Type: video/h264\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n".getBytes("UTF-8"));if(config!=null)out.write(config);clients.add(q);while(running){byte[] b=q.poll(3,TimeUnit.SECONDS);if(b!=null){out.write(b);out.flush();}}}else out.write("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n".getBytes("UTF-8"));}catch(Exception e){}finally{if(q!=null)clients.remove(q);try{s.close();}catch(Exception e){}}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==42&&g.length>0&&g[0]==0)openCamera();if(r==43&&g.length>0&&g[0]==0){telemetry=null;startTelemetryIfConfigured();}}
 protected void onDestroy(){if(raceControl!=null)raceControl.close();if(telemetry!=null)telemetry.stop();running=false;try{server.close();}catch(Exception e){}try{session.close();}catch(Exception e){}try{camera.close();}catch(Exception e){}try{encoder.stop();encoder.release();}catch(Exception e){}thread.quitSafely();super.onDestroy();}
}